```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <vector>
#include <algorithm>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("sprzedaz.txt");
    string sprzedawca, produkt;
    int sztuk;
    map<string, int> suma;
    while (plik >> sprzedawca >> produkt >> sztuk) {
        suma[sprzedawca] += sztuk;
    }

    cout << "a) Laczna sprzedaz:" << endl;
    int total = 0;
    for (auto &p : suma) {
        cout << "   " << p.first << ": " << p.second << endl;
        total += p.second;
    }

    vector<pair<int, string>> ranking;
    for (auto &p : suma) ranking.push_back({p.second, p.first});
    sort(ranking.begin(), ranking.end(), [](auto &a, auto &b) {
        if (a.first != b.first) return a.first > b.first;
        return a.second < b.second;
    });

    cout << endl << "b) TOP 3 sprzedawcow:" << endl;
    for (int i = 0; i < 3 && i < (int)ranking.size(); i++) {
        cout << "   " << i+1 << ". " << ranking[i].second << ": " << ranking[i].first << endl;
    }

    cout << endl << "c) Srednia sprzedaz: " << fixed << setprecision(2)
         << (double)total / suma.size() << endl;
    return 0;
}
```

